func flush_native_previews() -> String:
	for id in simulations.keys():
		var simulation: RefCounted=simulations[id]
		if not simulation is Secondary or not simulation.native_backend:continue
		var error: String=simulation.flush_native_preview(app.frame,recording.active,app.renderer.world_runtime)
		if not error.is_empty():
			disable_hair(id)
			return error
	return ""

